import { mediaWidths } from '@portfolio/tokens/media';

export type VariantFormat = 'avif' | 'webp';

/** Widths generated by scripts/build-media.ts for an original of the given width (never upscaled). */
export function variantWidths(originalWidth: number): number[] {
  return [...new Set(mediaWidths.map((width) => Math.min(width, originalWidth)))];
}

/** "/media/a/b.jpg" → "/media/a/b-480.avif 480w, /media/a/b-960.avif 960w, …" */
export function srcSet(src: string, originalWidth: number, format: VariantFormat): string {
  const base = src.replace(/\.(jpg|png)$/, '');
  return variantWidths(originalWidth)
    .map((width) => `${base}-${String(width)}.${format} ${String(width)}w`)
    .join(', ');
}
